<div id="emergencyConfirm" class="overlay-card hidden emergency-confirm"><div class="emergency-icon">⚠️</div><h3>درخواست استراحت اضطراری</h3><p>فقط در شرایط اضطراری استفاده شود.</p><div class="actions" style="justify-content:center"><button class="btnx btn-danger" onclick="confirmEmergency()">تأیید درخواست</button><button class="btnx" onclick="closeEmergency()">لغو</button></div></div>
<div id="toast"></div>
<script>
window.CURRENT_USERNAME=<?=json_encode($user['username'])?>;window.CURRENT_ROLE='expert';
function toggleTheme(){document.body.classList.toggle('light');localStorage.setItem('shaya-theme',document.body.classList.contains('light')?'light':'dark')}
if(localStorage.getItem('shaya-theme')==='light')document.body.classList.add('light');
function toast(t){let x=document.createElement('div');x.className='toastx';x.textContent=t;document.body.appendChild(x);setTimeout(()=>x.remove(),3200)}
async function post(u,d={}){let r=await fetch(u,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:new URLSearchParams(d),credentials:'same-origin',cache:'no-store'});return r.json()}
function sendRest(type){if(type==='emergency'){document.getElementById('emergencyConfirm').classList.remove('hidden');return;}submitRest('normal')}
function closeEmergency(){document.getElementById('emergencyConfirm').classList.add('hidden')}
function confirmEmergency(){closeEmergency();submitRest('emergency')}
async function submitRest(type){try{let r=await post('ajax_request_rest.php',{request_type:type});toast(r.message||'');if(r.success)setTimeout(()=>location.reload(),250)}catch(e){toast('ارسال درخواست انجام نشد؛ دوباره تلاش کنید.')}}
async function cancelRest(id){let r=await post('ajax_cancel_request.php',{request_id:id});toast(r.message||'');if(r.success)location.reload()}
async function endRest(id){if(!confirm('استراحت پایان یابد؟'))return;let r=await post('ajax_end_rest.php',{request_id:id});toast(r.message||'');if(r.success)location.reload()}
let lastStatus=<?=json_encode($active['status']??'none')?>;
async function poll(){let r=await post('ajax_expert_status.php');if(!r.success)return;if((r.request?.status||'none')!==lastStatus)location.reload();if(r.request?.status==='approved'){lastStatus='approved';let start=(+r.request.approved_ts||0)*1000;let d=(+r.request.duration_minutes||0)*60;function tick(){let rem=d-Math.floor((Date.now()-start)/1000);let t=document.getElementById('timer');if(!t)return;if(rem>=0){t.textContent=String(Math.floor(rem/60)).padStart(2,'0')+':'+String(rem%60).padStart(2,'0');}else{let x=-rem;t.textContent='+'+String(Math.floor(x/60)).padStart(2,'0')+':'+String(x%60).padStart(2,'0');document.getElementById('overtime')?.classList.remove('hidden')}}tick();if(!window._timer)window._timer=setInterval(tick,1000);}}
async function loadAnnouncement(){try{let r=await post('ajax_announcement.php',{action:'get'});let a=r.announcement,top=document.getElementById('globalAnnouncement');if(!a||!String(a.message||'').trim()){top?.classList.add('hidden');return;}if(top){top.classList.remove('hidden');document.getElementById('globalAnnouncementText').textContent=a.message;document.getElementById('globalAnnouncementMeta').textContent=(a.created_by_name||a.created_by)+' • '+a.created_at;}}catch(e){}}
loadAnnouncement();setInterval(loadAnnouncement,5000);poll();setInterval(poll,1500);</script></body></html>
